return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'de_CH_informal','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:03+00:00','po-revision-date'=>'2026-10-31T05:53:03+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Ergänzt fehlende Übersetzungen für die Plugins und Themes, die bereits auf deiner Website installiert sind.','Translations'=>'Übersetzungen','Babilim Settings'=>'Babilim-Einstellungen','Settings'=>'Einstellungen','You are not allowed to do this.'=>'Du bist nicht berechtigt, das zu tun.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Wähle weniger Komponenten aus: maximal %1$d Operationen pro Durchlauf (du hast %2$d ausgewählt).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Diese Komponente ist auf dieser Website nicht installiert, daher kann dafür keine Übersetzung angefordert werden.','Already installed.'=>'Scho installiert.','Downloaded and installed.'=>'Heruntergeladen und installiert.','Babilim has not been enabled for this site yet.'=>'Babilim wurde für diese Website noch nicht aktiviert.','No build is available to download for this locale.'=>'Für diese Sprache steht kein Build zum Herunterladen zur Verfügung.','Rolled back to the previous build.'=>'Auf den vorherigen Build zurückgesetzt.','Rolled back and reported.'=>'Zurückgesetzt und gemeldet.','Rolled back, but the report could not be sent: %s'=>'Zurückgesetzt, aber die Meldung konnte nicht gesendet werden: %s','Removed.'=>'Entfernt.','Translation requested.'=>'Übersetzung angefordert.','This component was already uploaded. Babilim is checking it now.'=>'Diese Komponente wurde bereits hochgeladen. Babilim prüft sie gerade.','Upload cancelled.'=>'Upload abbrochen.','Upload complete — translation requested.'=>'Upload abgeschlossen – Übersetzung ange